@Entity(tableName = "books", foreignKeys = [ForeignKey(
    entity = Author::class, parentColumns = ["id"], childColumns = ["author_id"],
    onDelete = ForeignKey.CASCADE)])
data class Book(
    @PrimaryKey val id: Long,
    @ColumnInfo(name = "author_id") val authorId: Long,
)

@Query("SELECT * FROM authors JOIN books ON books.author_id = authors.id")
suspend fun booksWithAuthor(): Map<Author, List<Book>>   // multimap relation
